/// A preset or sink problem; the text can be shown.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum DownmixError {
    /// The downmix sink is not there (the applemusic-downmix service is not running).
    #[error("{0}")]
    NotRunning(String),
    /// A preset key or a value the sink does not have.
    #[error("{0}")]
    Invalid(String),
    /// A program could not be run, or the sink did not take the controls.
    #[error("{0}")]
    Failed(String),
}

// --- the programs of the sink -----------------------------------------------------

/// What a program left behind.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct Output {
    /// The exit status; `None` when a signal ended the program.
    pub status: Option<i32>,
    pub stdout: String,
    pub stderr: String,
}

/// Why a program gave no output.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RunError {
    /// There is no such program.
    NotFound,
    PermissionDenied,
    /// Still running at the time limit; it was stopped.
    Timeout,
    /// Any other failure to start it or to wait for it.
    Other,
}

impl RunError {
    fn of(error: &io::Error) -> RunError {
        match error.kind() {
            io::ErrorKind::NotFound => RunError::NotFound,
            io::ErrorKind::PermissionDenied => RunError::PermissionDenied,
            _ => RunError::Other,
        }
    }

    /// The name this failure has in the engine's messages ("pw-cli failed (FileNotFoundError)"):
    /// the Python exception's.
    pub fn name(&self) -> &'static str {
        match self {
            RunError::NotFound => "FileNotFoundError",
            RunError::PermissionDenied => "PermissionError",
            RunError::Timeout => "TimeoutExpired",
            RunError::Other => "OSError",
        }
    }
}

/// Runs the sink's command-line programs (`pw-cli`, `pw-dump`). Every such call of this module
/// and of [`crate::eq`] goes through the one runner of a [`Downmix`]; tests pass their own, so
/// they never reach a real sink.
pub trait Runner: Send + Sync {
    /// Run `argv` (the program first) to its end and collect what it printed. `timeout` `None`
    /// waits without limit.
    fn run(&self, argv: &[&str], timeout: Option<Duration>) -> Result<Output, RunError>;
}

impl<F> Runner for F
where
    F: Fn(&[&str], Option<Duration>) -> Result<Output, RunError> + Send + Sync,
{
    fn run(&self, argv: &[&str], timeout: Option<Duration>) -> Result<Output, RunError> {
        self(argv, timeout)
    }
}

/// The real programs, found on the `PATH`, started without a shell and without input.
#[derive(Debug, Clone, Copy, Default)]
pub struct Programs;

/// Read a pipe to its end on a thread of its own, so that a full pipe never stalls the program.
/// False when the thread could not be started.
fn drain(pipe: Option<impl Read + Send + 'static>, sender: mpsc::Sender<(bool, Vec<u8>)>, is_stdout: bool) -> bool {
    let read = move || {
        let mut bytes = Vec::new();
        if let Some(mut pipe) = pipe {
            let _ = pipe.read_to_end(&mut bytes);
        }
        let _ = sender.send((is_stdout, bytes));
    };
    std::thread::Builder::new().name("amui-program-output".into()).spawn(read).is_ok()
}

/// Collect what both pipes carried and how the program ended, by the deadline.
fn finish(
    child: &mut Child,
    pipes: &mpsc::Receiver<(bool, Vec<u8>)>,
    deadline: Option<Instant>,
) -> Result<Output, RunError> {
    let mut output = Output::default();
    for _ in 0..2 {
        let (is_stdout, bytes) = match deadline {
            None => pipes.recv().map_err(|_| RunError::Other)?,
            Some(deadline) => {
                let left = deadline.saturating_duration_since(Instant::now());
                pipes.recv_timeout(left).map_err(|error| match error {
                    mpsc::RecvTimeoutError::Timeout => RunError::Timeout,
                    mpsc::RecvTimeoutError::Disconnected => RunError::Other,
                })?
            }
        };
        let text = String::from_utf8_lossy(&bytes).into_owned();
        if is_stdout {
            output.stdout = text;
        } else {
            output.stderr = text;
        }
    }
    // both pipes are closed: the program has ended or is about to
    let status = match deadline {
        None => child.wait().map_err(|_| RunError::Other)?,
        Some(deadline) => loop {
            match child.try_wait().map_err(|_| RunError::Other)? {
                Some(status) => break status,
                None if Instant::now() >= deadline => return Err(RunError::Timeout),
                None => std::thread::sleep(Duration::from_millis(1)),
            }
        },
    };
    output.status = status.code();
    Ok(output)
}

impl Runner for Programs {
    fn run(&self, argv: &[&str], timeout: Option<Duration>) -> Result<Output, RunError> {
        let Some((program, arguments)) = argv.split_first() else { return Err(RunError::Other) };
        let deadline = timeout.and_then(|limit| Instant::now().checked_add(limit));
        let mut child = Command::new(program)
            .args(arguments)
            .stdin(Stdio::null())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
            .map_err(|error| RunError::of(&error))?;
        let (sender, pipes) = mpsc::channel();
        let reading = drain(child.stdout.take(), sender.clone(), true) && drain(child.stderr.take(), sender, false);
        let outcome = if reading { finish(&mut child, &pipes, deadline) } else { Err(RunError::Other) };
        if outcome.is_err() {
            // out of time or out of order: the program is stopped and not left behind
            let _ = child.kill();
            let _ = child.wait();
        }
        outcome
    }
}

