/// The Q of the two biquads that make the LFE's 4th-order Butterworth low-pass.
pub fn bw4_q() -> [f64; 2] {
    use std::f64::consts::PI;
    [1.0 / (2.0 * (PI / 8.0).cos()), 1.0 / (2.0 * (3.0 * PI / 8.0).cos())]
}

/// The kinds of filter the sink's headphone EQ has slots for.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum FilterType {
    /// Low shelf.
    #[serde(rename = "LSC")]
    Lsc,
    /// Peaking.
    #[serde(rename = "PK")]
    Pk,
    /// High shelf.
    #[serde(rename = "HSC")]
    Hsc,
}

impl FilterType {
    /// In the order of the sink's slots.
    pub const ALL: [FilterType; 3] = [FilterType::Lsc, FilterType::Pk, FilterType::Hsc];

    pub fn as_str(&self) -> &'static str {
        match self {
            FilterType::Lsc => "LSC",
            FilterType::Pk => "PK",
            FilterType::Hsc => "HSC",
        }
    }

    pub fn parse(text: &str) -> Option<FilterType> {
        FilterType::ALL.into_iter().find(|kind| kind.as_str() == text)
    }

    /// How many filters of this kind one side of the sink holds.
    pub fn slots(&self) -> usize {
        EQ_SLOTS.iter().find(|(kind, _, _)| kind == self).map_or(0, |(_, _, slots)| *slots)
    }
}

impl std::fmt::Display for FilterType {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.as_str())
    }
}

/// One filter of a headphone EQ preset: `{"type": "PK", "freq": 105.0, "gain": -2.6, "q": 0.7}`.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
pub struct Filter {
    #[serde(rename = "type")]
    pub kind: FilterType,
    /// Hz.
    pub freq: f64,
    /// dB.
    pub gain: f64,
    pub q: f64,
}

/// EQ slots per side (kind, PipeWire's biquad, how many). Filters of one type commute, so a
/// preset's filters fill the slots of their type in any order; unused slots stay at 0 dB
