pub const EQ_SLOTS: [(FilterType, &str, usize); 3] =
    [(FilterType::Lsc, "bq_lowshelf", 4), (FilterType::Pk, "bq_peaking", 24), (FilterType::Hsc, "bq_highshelf", 4)];

